-- MediCare HMS: MySQL 8 schema (generated by scripts/export_schema.py)
CREATE DATABASE IF NOT EXISTS hospital_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hospital_db;

CREATE TABLE departments (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(80) NOT NULL, 
	description VARCHAR(255), 
	PRIMARY KEY (id), 
	UNIQUE (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


CREATE TABLE roles (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(30) NOT NULL, 
	description VARCHAR(200), 
	PRIMARY KEY (id), 
	UNIQUE (name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


CREATE TABLE users (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	username VARCHAR(40) NOT NULL, 
	full_name VARCHAR(120) NOT NULL, 
	email VARCHAR(120) NOT NULL, 
	password_hash VARCHAR(255) NOT NULL, 
	role_id INTEGER NOT NULL, 
	is_active BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	last_login DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (username), 
	UNIQUE (email), 
	FOREIGN KEY(role_id) REFERENCES roles (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_users_role_id ON users (role_id);

CREATE TABLE doctors (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	user_id INTEGER NOT NULL, 
	department_id INTEGER NOT NULL, 
	specialization VARCHAR(100) NOT NULL, 
	license_no VARCHAR(40) NOT NULL, 
	phone VARCHAR(20), 
	consultation_fee NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(department_id) REFERENCES departments (id), 
	UNIQUE (license_no)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_doctors_department_id ON doctors (department_id);

CREATE TABLE patients (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_code VARCHAR(20) NOT NULL, 
	first_name VARCHAR(60) NOT NULL, 
	last_name VARCHAR(60) NOT NULL, 
	dob DATE NOT NULL, 
	gender VARCHAR(10) NOT NULL, 
	phone VARCHAR(20) NOT NULL, 
	email VARCHAR(120), 
	address VARCHAR(255), 
	blood_group VARCHAR(5), 
	emergency_contact VARCHAR(120), 
	allergies VARCHAR(255), 
	is_active BOOL NOT NULL, 
	created_at DATETIME NOT NULL, 
	created_by INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (patient_code), 
	FOREIGN KEY(created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_patients_name ON patients (last_name, first_name);
CREATE INDEX ix_patients_phone ON patients (phone);

CREATE TABLE appointments (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	patient_id INTEGER NOT NULL, 
	doctor_id INTEGER NOT NULL, 
	start_at DATETIME NOT NULL, 
	end_at DATETIME NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	reason VARCHAR(255), 
	slot_key VARCHAR(40), 
	created_by INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_appt_times CHECK (end_at > start_at), 
	CONSTRAINT ck_appt_status CHECK (status IN ('scheduled','completed','cancelled','no_show')), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id), 
	UNIQUE (slot_key), 
	FOREIGN KEY(created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_appt_doctor_start ON appointments (doctor_id, start_at);
CREATE INDEX ix_appt_patient_start ON appointments (patient_id, start_at);

CREATE TABLE doctor_schedules (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	doctor_id INTEGER NOT NULL, 
	weekday SMALLINT NOT NULL, 
	start_time TIME NOT NULL, 
	end_time TIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT uq_schedule_window UNIQUE (doctor_id, weekday, start_time), 
	CONSTRAINT ck_schedule_weekday CHECK (weekday BETWEEN 0 AND 6), 
	CONSTRAINT ck_schedule_times CHECK (end_time > start_time), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


CREATE TABLE invoices (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	invoice_no VARCHAR(24) NOT NULL, 
	patient_id INTEGER NOT NULL, 
	appointment_id INTEGER, 
	status VARCHAR(10) NOT NULL, 
	discount NUMERIC(10, 2) NOT NULL, 
	notes VARCHAR(255), 
	created_by INTEGER, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_invoice_status CHECK (status IN ('unpaid','partial','paid','void')), 
	CONSTRAINT ck_invoice_discount CHECK (discount >= 0), 
	UNIQUE (invoice_no), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id), 
	FOREIGN KEY(created_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_invoices_appointment_id ON invoices (appointment_id);
CREATE INDEX ix_invoices_patient_id ON invoices (patient_id);

CREATE TABLE medical_records (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	appointment_id INTEGER NOT NULL, 
	patient_id INTEGER NOT NULL, 
	doctor_id INTEGER NOT NULL, 
	vitals VARCHAR(255), 
	diagnosis TEXT NOT NULL, 
	notes TEXT, 
	follow_up_date DATE, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (appointment_id), 
	FOREIGN KEY(appointment_id) REFERENCES appointments (id), 
	FOREIGN KEY(patient_id) REFERENCES patients (id), 
	FOREIGN KEY(doctor_id) REFERENCES doctors (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_medical_records_patient_id ON medical_records (patient_id);

CREATE TABLE invoice_items (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	invoice_id INTEGER NOT NULL, 
	description VARCHAR(200) NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_item_qty CHECK (quantity > 0), 
	CONSTRAINT ck_item_price CHECK (unit_price >= 0), 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_invoice_items_invoice_id ON invoice_items (invoice_id);

CREATE TABLE payments (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	invoice_id INTEGER NOT NULL, 
	amount NUMERIC(10, 2) NOT NULL, 
	method VARCHAR(12) NOT NULL, 
	reference VARCHAR(60), 
	paid_at DATETIME NOT NULL, 
	received_by INTEGER, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_payment_amount CHECK (amount > 0), 
	CONSTRAINT ck_payment_method CHECK (method IN ('cash','card','upi','insurance')), 
	FOREIGN KEY(invoice_id) REFERENCES invoices (id), 
	FOREIGN KEY(received_by) REFERENCES users (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_payments_invoice_id ON payments (invoice_id);

CREATE TABLE prescriptions (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	record_id INTEGER NOT NULL, 
	medicine VARCHAR(120) NOT NULL, 
	dosage VARCHAR(60) NOT NULL, 
	frequency VARCHAR(60) NOT NULL, 
	duration_days INTEGER NOT NULL, 
	PRIMARY KEY (id), 
	FOREIGN KEY(record_id) REFERENCES medical_records (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE INDEX ix_prescriptions_record_id ON prescriptions (record_id);

INSERT IGNORE INTO roles (name, description) VALUES
  ('admin','Full system access'),('doctor','Clinical access to own patients'),
  ('receptionist','Front desk: patients, appointments, billing');
